@OptIn(ExperimentalCoroutinesApi::class)
class InboxReadMarkerTest {
    private fun fixture(name:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$name.json")!!.bufferedReader().use {it.readText()}
    private fun context(o:JSONObject)=InboxConversationFilesContext(o.getInt("business"),o.getInt("conversation"),o.getInt("epoch"),o.getInt("revision"))
    private fun repository()=APIReadRepository(ReadTransport {q->val name=if(q.path=="/api/mobile/v1/inbox/")"inbox-${q.query["business"]}"else "inbox-${q.query["business"]}-${q.path.trimEnd('/').substringAfterLast('/')}";ReadResponse(200,fixture(name))})
    private fun files()=APIInboxConversationFilesRepository(FixtureInboxConversationFilesTransport.fromJSON(fixture("inbox-conversation-files")))
    private fun source()=APIInboxReadMarkerRepository(FixtureInboxReadMarkerReadTransport.fromJSON(fixture("inbox-read-markers")))
    private class Held(override val grants:List<SyntheticInboxReadMarkerGrant>):SyntheticInboxReadMarkerPort {val attempts=mutableListOf<InboxReadMarkerAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxReadMarkerOutcome>>();override suspend fun execute(a:InboxReadMarkerAttempt):SyntheticInboxReadMarkerOutcome {attempts+=a;return CompletableDeferred<SyntheticInboxReadMarkerOutcome>().also {pending+=it}.await()}}
    private class ReplyPort(override val grants:List<SyntheticInboxReplyGrant>):SyntheticInboxReplyPort {var calls=0;override suspend fun execute(attempt:InboxReplyAttempt):SyntheticInboxReplyOutcome {++calls;return SyntheticInboxReplyOutcome.Unknown}}
    private class HandoffPort(override val grants:List<SyntheticHandoffGrant>):SyntheticHandoffPort {var calls=0;override suspend fun execute(attempt:HandoffAttempt):SyntheticHandoffOutcome {++calls;return SyntheticHandoffOutcome.Unknown}}
    private class RetryPort(override val grants:List<SyntheticInboxRetryGrant>):SyntheticInboxRetryPort {var calls=0;override suspend fun execute(attempt:InboxRetryAttempt):SyntheticInboxRetryOutcome {++calls;return SyntheticInboxRetryOutcome.Unknown}}
    private class AssignPort(override val grants:List<SyntheticInboxSelfAssignmentGrant>):SyntheticInboxSelfAssignmentPort {var calls=0;override suspend fun execute(a:InboxSelfAssignmentAttempt):SyntheticInboxSelfAssignmentOutcome {++calls;return SyntheticInboxSelfAssignmentOutcome.Unknown}}
    @Test fun exactRawSourceActionPlain200AndImmutableUnknownLedger()=runTest {
        val d=JSONObject(fixture("inbox-read-markers"));val c=context(d.getJSONObject("context"));val cases=d.getJSONArray("source_cases")
        for(i in 0 until cases.length()){val x=cases.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxReadMarkerSource.decode(x.getString("response_json"),context(x.getJSONObject("context")))!=null)}
        val s=InboxReadMarkerSource.decode(d.getString("source_json"),c)!!;val f=FixtureInboxReadMarkerPort.fromJSON(fixture("inbox-read-markers"));val auth=f.grants[0].authorization(c)!!;val ledger=InboxReadMarkerLedger()
        for(action in InboxReadMarkerAction.entries){val r=InboxReadMarkerReview(s,auth,action,1);val a=ledger.begin(r)!!;assertEquals("{}",a.preparedBody());assertEquals("/api/inbox/conversations/901/${action.wire}/",a.path);assertTrue(a.headers.isEmpty());assertTrue(a.query.isEmpty());assertNull(ledger.begin(r));assertFalse(ledger.acknowledge(auth,ledger.visible(auth)!!));ledger.complete(a,f.execute(a));val result=ledger.visible(auth)!!;assertEquals(InboxReadMarkerPhase.RESPONSE,result.phase);assertEquals(if(action==InboxReadMarkerAction.READ)0L else 1L,result.result!!.source.unreadCount);assertEquals(7L,result.attempt.review.source.unreadCount);ledger.complete(a,SyntheticInboxReadMarkerOutcome.Unknown);assertEquals(result,ledger.visible(auth));assertTrue(ledger.acknowledge(auth,result))}
        val receipts=d.getJSONArray("receipt_cases");for(i in 0 until receipts.length()){val x=receipts.getJSONObject(i);val action=InboxReadMarkerAction.entries.single {it.wire==x.getString("action")};val l=InboxReadMarkerLedger();val a=l.begin(InboxReadMarkerReview(s,auth,action,2))!!;val r=InboxReadMarkerReceipt.decode(x.getString("response_json"),a);assertEquals(x.getString("name"),x.getBoolean("valid"),r!=null);l.complete(a,SyntheticInboxReadMarkerOutcome.Response(200,x.getString("response_json")));assertEquals(if(r==null)InboxReadMarkerPhase.UNKNOWN else InboxReadMarkerPhase.RESPONSE,l.visible(auth)!!.phase);assertEquals(a,l.records[0].attempt)}
        val review=InboxReadMarkerReview(s,auth,InboxReadMarkerAction.READ,3);val a=ledger.begin(review)!!;ledger.complete(a,SyntheticInboxReadMarkerOutcome.Unknown);val unknown=ledger.visible(auth)!!;assertFalse(ledger.acknowledge(auth,unknown));val next=c.copy(epoch=2,revision=2);val na=f.grants[0].authorization(next)!!;val matching=InboxReadMarkerSource.decode(d.getString("read_response_json"),next)!!;assertEquals(unknown,ledger.visible(na));assertNull(ledger.begin(InboxReadMarkerReview(matching,na,InboxReadMarkerAction.UNREAD,4)));assertEquals(a,ledger.records.last().attempt)
        val other=SyntheticInboxReadMarkerGrant(101,901,6002,true).authorization(next)!!;assertNull(ledger.visible(other));assertTrue(ledger.blocked(101,901));assertNull(ledger.begin(InboxReadMarkerReview(matching,other,InboxReadMarkerAction.READ,5)));assertFalse(ledger.blocked(202,951))
        for(g in listOf(SyntheticInboxReadMarkerGrant(101,901,5001,false),SyntheticInboxReadMarkerGrant(202,901,5001,true),SyntheticInboxReadMarkerGrant(101,951,5001,true),SyntheticInboxReadMarkerGrant(101,901,0,true)))assertNull(g.authorization(c))
        for(status in listOf(201,400,403,409,500)){val l=InboxReadMarkerLedger();val t=l.begin(review)!!;l.complete(t,SyntheticInboxReadMarkerOutcome.Response(status,d.getString("read_response_json")));assertEquals(InboxReadMarkerPhase.UNKNOWN,l.visible(auth)!!.phase);assertFalse(l.acknowledge(auth,l.visible(auth)!!))}
        assertFalse(InboxReadMarkerReview(s.copy(unreadCount=-1),auth,InboxReadMarkerAction.READ,6).valid)
    }
    @Test fun actualParentReviewBothActionsKnownUnknownMatchingRereadAndABABarriers()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val f=FixtureInboxReadMarkerPort.fromJSON(fixture("inbox-read-markers"));val held=Held(f.grants);val log=mutableListOf<ReadRequest>();var matching=false;val base=FixtureInboxReadMarkerReadTransport.fromJSON(fixture("inbox-read-markers"));val source=APIInboxReadMarkerRepository(ReadTransport {q->log+=q;if(matching && q.path=="/api/inbox/conversations/901/")ReadResponse(200,JSONObject(fixture("inbox-read-markers")).getString("unread_response_json"))else base.get(q)})
        val rp=ReplyPort(FixtureInboxReplyPort(fixture("inbox-reply-outcome")).grants);val hp=HandoffPort(FixtureHandoffPort(fixture("inbox-handoff-outcome")).grants);val retry=RetryPort(FixtureInboxRetryPort(fixture("inbox-retry-message")).grants);val assign=AssignPort(FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment")).grants)
        val m=InboxViewModel(repository(),replySubmission=rp,handoffSubmission=hp,files=files(),messageFiles=APIInboxMessageFilesRepository(FixtureInboxRetryReadTransport(fixture("inbox-retry-message"))),retrySubmission=retry,assignmentRead=APIInboxSelfAssignmentRepository(FixtureInboxSelfAssignmentReadTransport.fromJSON(fixture("inbox-self-assignment"))),assignmentSubmission=assign,markerRead=source,markerSubmission=held)
        try {
            m.load(101,461);runCurrent();m.open(901);runCurrent();val original=m.state.thread;val c=m.fileMetadata!!;val replyContext=m.reply.state.context!!;m.openFiles(m.filesEntryControl);assertTrue(log.isEmpty());assertFalse(c.canPrepareMarker);c.loadMarker(c.control);c.loadAssignment(c.control);val observed=c.markerSource!!;val old=c.control;c.prepareMarker(InboxReadMarkerAction.READ,c.control);val r=c.markerReview!!;val ctrl=c.control;val reads=log.toList();c.loadAssignment(c.control);c.prepareAssignment(c.control);c.loadMarker(c.control);c.load(c.control);c.prepareMarker(InboxReadMarkerAction.UNREAD,old);c.backMarker(old);c.submitMarker(r,old);assertEquals(reads,log);assertEquals(r,c.markerReview);assertTrue(c.canSubmitMarker);assertFalse(c.canPrepareAssignment);assertNull(c.assignmentReview);assertTrue(held.attempts.isEmpty())
            val job=launch {c.submitMarker(r,ctrl)};runCurrent();val pending=c.markerRecord!!;c.submitMarker(r,c.control);c.acknowledgeMarker(pending,c.control);assertEquals(1,held.attempts.size);assertTrue(m.conversationCommandsBlocked);assertFalse(c.canLoadMarker);assertFalse(c.canLoadAssignment);m.closeFiles(m.filesPresentationControl);m.openReply(replyContext,m.control);m.openHandoff(m.handoff.entryControl,m.control);assertNull(m.reply.control);assertNull(m.handoff.control)
            m.reply.open(replyContext);m.reply.update(" Retained marker peer ",m.reply.inputControl);m.reply.prepare(m.reply.control);m.reply.submit(m.reply.state.review!!,m.reply.control);assertEquals(0,rp.calls);assertFalse(m.reply.canSubmit);m.reply.close(m.reply.returnControl);m.handoff.open(m.handoff.entryControl);m.handoff.update(" Retained marker handoff ",m.handoff.inputControl);m.handoff.prepare(m.handoff.control);m.handoff.submit(m.handoff.state.review!!,m.handoff.control);assertEquals(0,hp.calls);m.handoff.back(m.handoff.returnControl);m.handoff.back(m.handoff.returnControl)
            m.openMessageFiles(m.messageFilesEntryControl(m.state.thread!!.messages[1]));val message=m.messageMetadata!!;message.load(message.control);message.prepareRetry(message.control);assertFalse(message.canPrepareRetry);assertNull(message.retryReview);assertEquals(0,retry.calls);m.closeMessageFiles(m.messageFilesPresentationControl);m.openFiles(m.filesEntryControl);c.loadMarker(c.control);assertEquals(reads,log);assertEquals(pending,c.markerRecord);held.pending[0].complete(f.execute(held.attempts[0]));job.join();val result=c.markerRecord!!;assertEquals(InboxReadMarkerPhase.RESPONSE,result.phase);assertEquals(0L,result.result!!.source.unreadCount);assertEquals(observed,result.attempt.review.source);assertEquals(original,m.state.thread);c.acknowledgeMarker(result,ctrl);assertEquals(result,c.markerRecord);c.acknowledgeMarker(result,c.control);assertFalse(m.conversationCommandsBlocked);assertEquals(1,c.retainedMarkerCount)
            c.loadMarker(c.control);c.prepareMarker(InboxReadMarkerAction.UNREAD,c.control);val ur=c.markerReview!!;val uc=c.control;val uj=launch {c.submitMarker(ur,uc)};runCurrent();held.pending[1].completeExceptionally(IllegalStateException("synthetic failure"));uj.join();val unknown=c.markerRecord!!;matching=true;c.loadMarker(c.control);c.acknowledgeMarker(unknown,c.control);c.prepareMarker(InboxReadMarkerAction.READ,c.control);c.prepareAssignment(c.control);assertEquals(unknown,c.markerRecord);assertNull(c.markerReview);assertNull(c.assignmentReview);assertEquals(1L,c.markerSource!!.unreadCount);assertEquals(7L,unknown.attempt.review.source.unreadCount);assertEquals(InboxReadMarkerAction.UNREAD,unknown.attempt.review.action);assertEquals(2,held.attempts.size)
            m.closeFiles(m.filesPresentationControl);m.load(202,462);runCurrent();m.open(951);runCurrent();m.openFiles(m.filesEntryControl);c.loadMarker(c.control);assertNull(c.markerRecord);assertTrue(c.canPrepareMarker);m.closeFiles(m.filesPresentationControl);m.load(101,463);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);c.loadMarker(c.control);assertEquals(unknown,c.markerRecord);assertTrue(m.conversationCommandsBlocked);assertFalse(c.canPrepareMarker)
        } finally {m.viewModelScope.cancel();Dispatchers.resetMain()}
    }
    @Test fun inverseUnknownPeersAndLateCommandPreserveCurrentBusinessDraft()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val f=FixtureInboxReadMarkerPort.fromJSON(fixture("inbox-read-markers"))
        try {
            for(kind in 0..3){val held=Held(f.grants);val rp=ReplyPort(FixtureInboxReplyPort(fixture("inbox-reply-outcome")).grants);val hp=HandoffPort(FixtureHandoffPort(fixture("inbox-handoff-outcome")).grants);val retry=RetryPort(FixtureInboxRetryPort(fixture("inbox-retry-message")).grants);val assign=AssignPort(FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment")).grants);val m=InboxViewModel(repository(),replySubmission=rp,handoffSubmission=hp,files=files(),messageFiles=APIInboxMessageFilesRepository(FixtureInboxRetryReadTransport(fixture("inbox-retry-message"))),retrySubmission=retry,assignmentRead=APIInboxSelfAssignmentRepository(FixtureInboxSelfAssignmentReadTransport.fromJSON(fixture("inbox-self-assignment"))),assignmentSubmission=assign,markerRead=source(),markerSubmission=held)
                try {m.load(101,470+kind);runCurrent();m.open(901);runCurrent()
                    if(kind==0){m.openReply(m.reply.state.context!!,m.control);m.reply.update(" Unknown reply ",m.reply.inputControl);m.reply.prepare(m.reply.control);m.reply.submit(m.reply.state.review!!,m.reply.control);assertEquals(1,rp.calls);m.reply.close(m.reply.returnControl)}
                    else if(kind==1){m.openHandoff(m.handoff.entryControl,m.control);m.handoff.update(" Unknown handoff ",m.handoff.inputControl);m.handoff.prepare(m.handoff.control);m.handoff.submit(m.handoff.state.review!!,m.handoff.control);assertEquals(1,hp.calls);m.handoff.back(m.handoff.returnControl)}
                    else if(kind==2){m.openMessageFiles(m.messageFilesEntryControl(m.state.thread!!.messages[1]));val c=m.messageMetadata!!;c.load(c.control);c.prepareRetry(c.control);c.submitRetry(c.retryReview!!,c.control);assertEquals(1,retry.calls);m.closeMessageFiles(m.messageFilesPresentationControl)}
                    else {m.openFiles(m.filesEntryControl);val c=m.fileMetadata!!;c.loadAssignment(c.control);c.prepareAssignment(c.control);c.submitAssignment(c.assignmentReview!!,c.control);assertEquals(1,assign.calls);m.closeFiles(m.filesPresentationControl)}
                    m.openFiles(m.filesEntryControl);val c=m.fileMetadata!!;c.loadMarker(c.control);c.prepareMarker(InboxReadMarkerAction.READ,c.control);c.prepareMarker(InboxReadMarkerAction.UNREAD,c.control);assertNotNull(c.markerSource);assertFalse(c.canPrepareMarker);assertNull(c.markerReview);assertTrue(held.attempts.isEmpty())
                } finally {m.viewModelScope.cancel()}
            }
            val held=Held(f.grants);val m=InboxViewModel(repository(),files=files(),markerRead=source(),markerSubmission=held)
            try {m.load(101,480);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);val c=m.fileMetadata!!;c.loadMarker(c.control);c.prepareMarker(InboxReadMarkerAction.READ,c.control);val r=c.markerReview!!;val ctrl=c.control;val j=launch {c.submitMarker(r,ctrl)};runCurrent();val a=held.attempts[0];m.closeFiles(m.filesPresentationControl);m.load(202,481);runCurrent();m.open(951);runCurrent();m.openReply(m.reply.state.context!!,m.control);m.reply.update(" Business B marker draft ",m.reply.inputControl);val peer=m.reply.control;val original=m.state.thread;val filesControl=c.control;held.pending[0].complete(f.execute(a));j.join();assertEquals(peer,m.reply.control);assertEquals(" Business B marker draft ",m.reply.state.text);assertEquals(original,m.state.thread);assertEquals(filesControl,c.control);assertNull(c.markerSource);assertNull(c.markerRecord);assertEquals(1,c.retainedMarkerCount)} finally {m.viewModelScope.cancel()}
        } finally {Dispatchers.resetMain()}
    }
    @Test fun cancelledAttemptExplicitRejectionNoPortAndLateGenericRead()=runTest {
        val f=FixtureInboxReadMarkerPort.fromJSON(fixture("inbox-read-markers"));val held=Held(f.grants);val c=InboxConversationFilesContext(101,901,490,1);val m=InboxConversationFilesModel(files(),markerRead=source(),markerPort=held);m.commandsBlocked={false};m.bind(c);m.open(m.control);m.loadMarker(m.control);m.prepareMarker(InboxReadMarkerAction.READ,m.control);val r=m.markerReview!!;val ctrl=m.control;val j=launch {m.submitMarker(r,ctrl)};runCurrent();held.pending[0].complete(SyntheticInboxReadMarkerOutcome.RejectedWithoutWrite);j.join();val rejected=m.markerRecord!!;assertEquals(InboxReadMarkerPhase.REJECTED,rejected.phase);m.acknowledgeMarker(rejected,m.control);m.prepareMarker(InboxReadMarkerAction.UNREAD,m.control);val cr=m.markerReview!!;val cc=m.control;val cancelled=launch {m.submitMarker(cr,cc)};runCurrent();cancelled.cancelAndJoin();assertEquals(InboxReadMarkerPhase.UNKNOWN,m.markerRecord!!.phase);assertEquals(cr,m.markerRecord!!.attempt.review);assertFalse(m.canPrepareMarker)
        val noPort=InboxConversationFilesModel(files(),markerRead=source());noPort.commandsBlocked={false};noPort.bind(c);noPort.open(noPort.control);noPort.loadMarker(noPort.control);noPort.prepareMarker(InboxReadMarkerAction.READ,noPort.control);assertNotNull(noPort.markerSource);assertFalse(noPort.canPrepareMarker);assertNull(noPort.markerReview)
        val deferred=CompletableDeferred<InboxReadMarkerSource>();val repo=object:InboxReadMarkerRepository {override suspend fun source(c:InboxConversationFilesContext)=deferred.await()};val late=InboxConversationFilesModel(files(),markerRead=repo,markerPort=f);late.bind(c);late.open(late.control);val before=late.control;val task=launch {late.loadMarker(before)};runCurrent();late.close(late.presentation);late.bind(InboxConversationFilesContext(202,951,491,1));late.open(late.control);val after=late.control;deferred.complete(source().source(c));task.join();assertEquals(after,late.control);assertNull(late.markerSource);assertFalse(late.markerLoading);assertNull(late.markerReview)
    }
}
